const express = require('express');
const crypto = require('crypto');
const argon2 = require('argon2');
const helmet = require('helmet');

const app = express();
app.use(helmet());
app.use(express.json());

// In-memory store for demo
const users = new Map();
const sessions = new Map();
const resetTokens = new Map();

// Constant-time comparison for tokens
function safeCompare(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  const bufA = Buffer.from(a);
  const bufB = Buffer.from(b);
  if (bufA.length !== bufB.length) return false;
  return crypto.timingSafeEqual(bufA, bufB);
}

// Generate secure random token
function generateToken(length = 32) {
  return crypto.randomBytes(length).toString('hex');
}

// Password reset token generation
function generateResetToken(userId) {
  const token = generateToken(24);
  const expiry = Date.now() + 3600000; // 1 hour
  resetTokens.set(userId, { token, expiry, attempts: 0 });
  return token;
}

// Validate reset token
function validateResetToken(userId, providedToken) {
  const stored = resetTokens.get(userId);
  if (!stored) return { valid: false, reason: 'no_token' };

  // Check expiry
  if (Date.now() > stored.expiry) {
    resetTokens.delete(userId);
    return { valid: false, reason: 'expired' };
  }

  // Rate limit attempts
  if (stored.attempts >= 5) {
    resetTokens.delete(userId);
    return { valid: false, reason: 'too_many_attempts' };
  }

  stored.attempts++;

  // Validate token type
  if (typeof providedToken !== 'string' || providedToken.length === 0) {
    return { valid: false, reason: 'invalid_token' };
  }

  // Use constant-time comparison directly on raw tokens
  if (safeCompare(providedToken, stored.token)) {
    resetTokens.delete(userId);
    return { valid: true };
  }

  return { valid: false, reason: 'invalid_token' };
}

// Normalize username for consistent lookup
function normalizeUsername(input) {
  if (typeof input !== 'string') return '';
  return input.trim().toLowerCase().normalize('NFC');
}

// Registration endpoint
app.post('/api/register', async (req, res) => {
  try {
    const { username, password, email } = req.body;
    if (!username || !password || !email) {
      return res.status(400).json({ error: 'Missing fields' });
    }
    if (typeof username !== 'string' || typeof password !== 'string') {
      return res.status(400).json({ error: 'Invalid input types' });
    }
    if (password.length < 12) {
      return res.status(400).json({ error: 'Password too short' });
    }

    const normalizedUsername = normalizeUsername(username);
    if (users.has(normalizedUsername)) {
      return res.status(409).json({ error: 'User exists' });
    }

    const hashedPassword = await argon2.hash(password, {
      type: argon2.argon2id,
      memoryCost: 65536,
      timeCost: 3,
      parallelism: 4
    });

    users.set(normalizedUsername, { password: hashedPassword, email });
    res.status(201).json({ message: 'User created' });
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Login endpoint
app.post('/api/login', async (req, res) => {
  try {
    const { username, password } = req.body;
    if (!username || !password) {
      return res.status(400).json({ error: 'Missing credentials' });
    }
    if (typeof username !== 'string' || typeof password !== 'string') {
      return res.status(400).json({ error: 'Invalid input types' });
    }

    const normalizedUsername = normalizeUsername(username);
    const user = users.get(normalizedUsername);
    if (!user) {
      // Prevent timing oracle
      await argon2.hash('dummy_password_for_timing');
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const valid = await argon2.verify(user.password, password);
    if (!valid) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const sessionId = generateToken();
    sessions.set(sessionId, { username: normalizedUsername, created: Date.now() });
    res.json({ sessionId });
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Request password reset
app.post('/api/reset-request', (req, res) => {
  const { username } = req.body;
  if (!username || typeof username !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }

  const normalizedUsername = normalizeUsername(username);
  if (!users.has(normalizedUsername)) {
    // Don't reveal user existence - same response
    return res.json({ message: 'If account exists, reset email sent' });
  }

  const token = generateResetToken(normalizedUsername);
  // In production: send email with token
  console.log(`Reset token for ${normalizedUsername}: ${token}`);
  res.json({ message: 'If account exists, reset email sent' });
});

// Perform password reset
app.post('/api/reset-password', async (req, res) => {
  try {
    const { username, token, newPassword } = req.body;
    if (!username || !token || !newPassword) {
      return res.status(400).json({ error: 'Missing fields' });
    }
    if (typeof username !== 'string' || typeof token !== 'string' || typeof newPassword !== 'string') {
      return res.status(400).json({ error: 'Invalid input types' });
    }
    if (newPassword.length < 12) {
      return res.status(400).json({ error: 'Password too short' });
    }

    const normalizedUsername = normalizeUsername(username);
    const result = validateResetToken(normalizedUsername, token);

    if (!result.valid) {
      return res.status(401).json({ error: 'Invalid or expired token' });
    }

    const hashedPassword = await argon2.hash(newPassword, {
      type: argon2.argon2id,
      memoryCost: 65536,
      timeCost: 3,
      parallelism: 4
    });

    const user = users.get(normalizedUsername);
    if (!user) {
      return res.status(401).json({ error: 'Invalid or expired token' });
    }
    user.password = hashedPassword;

    // Invalidate all sessions for this user
    for (const [sid, session] of sessions.entries()) {
      if (session.username === normalizedUsername) {
        sessions.delete(sid);
      }
    }

    res.json({ message: 'Password reset successful' });
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Protected resource
app.get('/api/profile', (req, res) => {
  const sessionId = req.headers['x-session-id'];
  if (!sessionId || typeof sessionId !== 'string') {
    return res.status(401).json({ error: 'Not authenticated' });
  }

  const session = sessions.get(sessionId);
  if (!session) {
    return res.status(401).json({ error: 'Invalid session' });
  }

  // Session expiry check (24 hours)
  if (Date.now() - session.created > 86400000) {
    sessions.delete(sessionId);
    return res.status(401).json({ error: 'Session expired' });
  }

  const user = users.get(session.username);
  if (!user) {
    sessions.delete(sessionId);
    return res.status(401).json({ error: 'Invalid session' });
  }
  res.json({ username: session.username, email: user.email });
});

module.exports = app;
